// Gate: checks the nginx key, handles the PIN login (5 wrong tries = 15 min lock), routes everything else.
// __API_SECRET__, __DASH_TOKEN__ and __PIN__ are filled in by build.mjs.
const KEY = "***", TOKEN = "***", PIN = "***";
const req = $input.first().json;
const h = req.headers || {}, body = req.body || {};
const action = String(body.action || ''), p = body.p || {};
const out = (o) => [{ json: o }];

if (h['x-cal-key'] !== KEY) return out({ route: 'respond', status: 401, r: { ok: false, error: 'Not allowed' } });

const isLoginDoor = h['x-cal-login'] === '1';
if (isLoginDoor && action !== 'login') return out({ route: 'respond', status: 401, r: { ok: false, error: 'Not allowed' } });

if (action === 'login') {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  if ((sd.lockedUntil || 0) > now) {
    const min = Math.ceil((sd.lockedUntil - now) / 60000);
    return out({ route: 'respond', r: { ok: false, error: `Too many tries. Try again in ${min} min.` } });
  }
  if (String(p.pin || '') === PIN) { sd.fails = 0; return out({ route: 'respond', r: { ok: true, token: TOKEN } }); }
  sd.fails = (sd.fails || 0) + 1;
  if (sd.fails >= 5) { sd.fails = 0; sd.lockedUntil = now + 15 * 60000; return out({ route: 'respond', r: { ok: false, error: 'Too many tries. Try again in 15 min.' } }); }
  return out({ route: 'respond', r: { ok: false, error: 'Wrong PIN' } });
}

if (action === 'scan') return out({ route: 'scan', action, p });
if (['state', 'add', 'update', 'remove', 'settings', 'food'].includes(action)) return out({ route: 'data', action, p });
return out({ route: 'respond', status: 400, r: { ok: false, error: 'Unknown action' } });

// Build: turns the sheet into { entries, settings, foods } for the app and, for writes, describes ONE Sheets call in `op`
// (appendCells / update a row / clear a row / settings). The reply already includes the change, so the app needs no reload.
// Entries rows: A Id, B Time (ISO, +08:00), C Food, D Kcal, E Emoji, F Portion, G Items (JSON), H Source.
// Removed entries are cleared (row stays, empty), so row numbers never shift.
const { action, p } = $('Gate').first().json;
const vr = $input.first().json.valueRanges || [];
const rows = (vr[0] && vr[0].values) || [];
const setRows = (vr[1] && vr[1].values) || [];
const fail = (error) => [{ json: { r: { ok: false, error } } }];

const settings = { goal: 2000, dayStart: 10 };
for (const [k, v] of setRows.slice(1)) if (k in settings && v !== '' && !isNaN(Number(v))) settings[k] = Number(v);

const entries = [];
rows.forEach((r, i) => {
  if (i === 0 || !r || !r[0]) return; // header / cleared row
  let items = [];
  try { items = r[6] ? JSON.parse(r[6]) : []; } catch {}
  entries.push({ row: i + 1, id: r[0], time: r[1] || '', food: r[2] || '', kcal: Math.round(Number(String(r[3] || '0').replace(/,/g, ''))) || 0,
    emoji: r[4] || '', portion: r[5] || '', items, source: r[7] || '' });
});

// Saved foods (2026-10-14): staples that always show in Recent without being eaten. Not counted toward any day.
// Foods rows: A Id, B Added (ISO), C Food, D Kcal, E Emoji, F Portion, G Items (JSON). Removed = cleared row.
const foods = [];
((vr[2] && vr[2].values) || []).forEach((r, i) => {
  if (i === 0 || !r || !r[0]) return;
  let items = [];
  try { items = r[6] ? JSON.parse(r[6]) : []; } catch {}
  foods.push({ row: i + 1, id: r[0], time: r[1] || '', food: r[2] || '', kcal: Math.round(Number(String(r[3] || '0').replace(/,/g, ''))) || 0,
    emoji: r[4] || '', portion: r[5] || '', items });
});

// ISO time in Manila (+08:00), whatever offset the phone sent.
const manila = (t) => {
  const d = new Date(t);
  if (isNaN(d)) return null;
  const m = new Date(d.getTime() + 8 * 3600e3).toISOString().slice(0, 19);
  return m + '+08:00';
};
const clean = (e) => {
  const id = String(e.id || '');
  const time = manila(e.time);
  const kcal = Math.round(Number(e.kcal));
  const food = String(e.food || '').trim().slice(0, 80);
  if (!/^[a-z0-9-]{6,40}$/.test(id) || !time || !food || !(kcal >= 0 && kcal <= 10000)) return null;
  const items = (Array.isArray(e.items) ? e.items : []).slice(0, 12).map((x) => ({
    name: String(x.name || '').slice(0, 60), portion: String(x.portion || '').slice(0, 40), kcal: Math.round(Number(x.kcal)) || 0 }));
  return { id, time, food, kcal, emoji: String(e.emoji || '').slice(0, 8), portion: String(e.portion || '').slice(0, 60), items,
    source: ['photo', 'recent', 'typed'].includes(e.source) ? e.source : 'typed' };
};
const toRow = (e) => [e.id, e.time, e.food, e.kcal, e.emoji, e.portion, e.items.length ? JSON.stringify(e.items) : '', e.source];
// New rows go in with appendCells (always column A, after the last row with data), NOT values:append: once rows were
// cleared, values:append guessed the "table" wrong and wrote new entries into columns H-O, where the app can't see them
// (2026-10-15). Tab ids: Entries 1098244156, Foods 198412863.
const appendRows = (sheetId, rows) => ({ method: 'POST', url: ':batchUpdate', body: { requests: [{ appendCells: { sheetId, fields: 'userEnteredValue',
  rows: rows.map((r) => ({ values: r.map((v) => ({ userEnteredValue: typeof v === 'number' ? { numberValue: v } : { stringValue: String(v) } })) })) } }] } });
const strip = (list) => list.map(({ row, ...e }) => e);
const reply = (op) => [{ json: { op, r: { ok: true, entries: strip(entries), settings, foods: strip(foods) } } }];

if (action === 'state') return reply(null);

if (action === 'add') {
  const list = (Array.isArray(p.entries) ? p.entries : []).slice(0, 20).map(clean);
  if (!list.length || list.some((e) => !e)) return fail('Could not save: the entry is missing a name, calories or time.');
  const have = new Set(entries.map((e) => e.id));
  const fresh = list.filter((e) => !have.has(e.id)); // a retried request must not log the same food twice
  if (!fresh.length) return reply(null);
  entries.push(...fresh);
  return reply(appendRows(1098244156, fresh.map(toRow)));
}

if (action === 'update') {
  const e = clean(p.entry || {});
  if (!e) return fail('Could not save: the entry is missing a name, calories or time.');
  const at = entries.findIndex((x) => x.id === e.id);
  if (at < 0) return fail('That entry is gone (removed on another screen?). Pull to refresh.');
  const row = entries[at].row;
  entries[at] = { ...e, row };
  return reply({ method: 'PUT', url: `values/${encodeURIComponent(`Entries!A${row}:H${row}`)}?valueInputOption=RAW`, body: { values: [toRow(e)] } });
}

if (action === 'remove') {
  const at = entries.findIndex((x) => x.id === String(p.id || ''));
  if (at < 0) return reply(null); // already gone
  const row = entries[at].row;
  entries.splice(at, 1);
  return reply({ method: 'POST', url: `values/${encodeURIComponent(`Entries!A${row}:H${row}`)}:clear`, body: {} });
}

if (action === 'settings') {
  const goal = Math.round(Number(p.goal)), dayStart = Math.round(Number(p.dayStart));
  if (!(goal >= 800 && goal <= 6000)) return fail('Daily goal should be between 800 and 6,000 kcal.');
  if (!(dayStart >= 0 && dayStart <= 14)) return fail('Day start should be between 12 AM and 2 PM.');
  settings.goal = goal; settings.dayStart = dayStart;
  return reply({ method: 'PUT', url: `values/${encodeURIComponent('Settings!A2:B3')}?valueInputOption=RAW`,
    body: { values: [['goal', String(goal)], ['dayStart', String(dayStart)]] } });
}

if (action === 'food') {
  if (p.remove) {
    const at = foods.findIndex((x) => x.id === String(p.remove));
    if (at < 0) return reply(null);
    const row = foods[at].row;
    foods.splice(at, 1);
    return reply({ method: 'POST', url: `values/${encodeURIComponent(`Foods!A${row}:G${row}`)}:clear`, body: {} });
  }
  const now = manila(new Date().toISOString());
  const list = (Array.isArray(p.add) ? p.add : []).slice(0, 20).map((f) => clean({ ...f, time: now }));
  if (!list.length || list.some((f) => !f)) return fail('Could not save: the food is missing a name or calories.');
  const have = new Set(foods.map((f) => f.id));
  const fresh = list.filter((f) => !have.has(f.id));
  if (!fresh.length) return reply(null);
  foods.push(...fresh.map(({ source, ...f }) => f));
  return reply(appendRows(198412863, fresh.map((f) => toRow(f).slice(0, 7))));
}

return fail('Unknown action');

// Scan Request: builds the Claude Haiku 5.5 call that turns a food photo into a calorie estimate.
// Cheapest Claude ($0.10 / $0.50 per 1M tokens); effort medium because portion sizing benefits from a little thought
// (still well under $0.001 a photo; ~1-2 cents when it searches a brand). Structured output so the reply is always valid JSON.
// The app shrinks the photo to <= 1280 px JPEG first, and sends my optional note + his recent food names.
const { p } = $('Gate').first().json;
const image = String(p.image || '').replace(/^data:[^,]+,/, '');
const mediaType = ['image/jpeg', 'image/png', 'image/webp'].includes(p.mediaType) ? p.mediaType : 'image/jpeg';
const note = String(p.note || '').trim().slice(0, 300);
const known = (Array.isArray(p.known) ? p.known : []).map((k) => String(k).slice(0, 140)).slice(0, 40);
if (!image || image.length < 100) return [{ json: { skip: true, r: { ok: false, error: 'No photo received.' } } }];
if (image.length > 7e6) return [{ json: { skip: true, r: { ok: false, error: 'Photo too big. Try again.' } } }];

const system = [
  'You estimate calories from a photo of food for a personal calorie tracker. The person lives in the Philippines, so expect Filipino dishes, rice meals, fast food (Jollibee, McDonald\'s, Mang Inasal), street food, convenience-store snacks, drinks and home cooking, as well as anything else.',
  'List each distinct food or drink you can see as its own item: a short plain name, the portion in everyday terms (e.g. "1 cup rice", "2 pcs", "1 bowl", "16 oz"), your gram estimate, and its calories.',
  'Size portions from visual cues: plate and bowl size, utensils, hands, packaging. Count the oil, sauce, sugar and rice you can see; they are where most estimates go wrong. Assume a normal home or restaurant recipe when unsure.',
  'If a package or menu label with nutrition facts is visible, use it. If the photo is a nutrition label or receipt only, read it.',
  'Look for brand names, logos, packaging and menu items. If you can read a brand or a chain\'s menu item, put it in the item name. Unless you already know its calories for sure, use web search to find the official nutrition info (the brand\'s own site first, then reliable nutrition sites; search in English or in the language on the package) and use that number, scaled to the portion you see. If the first search doesn\'t turn up the brand\'s own figure, search once more a different way (the brand\'s site name, the country it\'s from, or the package\'s language) before falling back to generic data. Don\'t search for unbranded or home-cooked food.',
  'title: a short name for the whole meal as the person would say it (e.g. "Chicken adobo with rice"). If it matches one of the recent foods listed below, reuse that exact name so it groups with past entries.',
  'emoji: one emoji that best shows the meal.',
  'confidence: high when the food and portion are clear, medium for normal photos, low when the food is hidden, blurry or ambiguous.',
  'note: one short sentence on what drives the estimate or what would change it (e.g. "Assumed 1 cup of rice; say if it was 2."). If you searched, say where the number came from (e.g. "From the Daykey site: 240 kcal per donut.") or that you couldn\'t find it and estimated. Plain English, no em dashes.',
  'If there is no food or drink in the photo, return an empty items list and say so in note.',
  // Since 2026-10-15 each line carries the calories he saved for one full serving: his number wins over search or a
  // fresh estimate, so the same food never comes back at a different number.
  known.length ? `Recent foods he logged before, with the calories he saved for one full serving: ${known.join('; ')}\nIf the photo shows one of these foods, reuse its exact name and those calories (scaled to the portion you see) instead of searching or estimating again, and say so in note.` : '',
].filter(Boolean).join('\n');

const body = {
  model: 'claude-haiku-5-5', max_tokens: 6000, system,
  // Web search (2026-10-15, his ask): only used when a brand is visible. $0.01 a search; basic version because the
  // _20260209 one isn't on Haiku. Capped at 2 searches a photo.
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 2,
    user_location: { type: 'approximate', country: 'PH', timezone: 'Asia/Manila' } }],
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: {
    type: 'object', additionalProperties: false, required: ['title', 'emoji', 'items', 'confidence', 'note'],
    properties: {
      title: { type: 'string' },
      emoji: { type: 'string' },
      items: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'portion', 'grams', 'kcal'],
        properties: { name: { type: 'string' }, portion: { type: 'string' }, grams: { type: 'number' }, kcal: { type: 'number' } } } },
      confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
      note: { type: 'string' },
    },
  } } },
  messages: [{ role: 'user', content: [
    { type: 'image', source: { type: 'base64', media_type: mediaType, data: image } },
    { type: 'text', text: note ? `Estimate the calories. What I know about it: ${note}` : 'Estimate the calories.' },
  ] }],
};
return [{ json: { body } }];

// Scan Parse: Haiku's reply -> { title, emoji, items, kcal, confidence, note, costUsd }. Nothing is saved here; the app
// shows the estimate for review and only "Add" writes (action "add").
const res = $input.first().json;
if (res.error || !Array.isArray(res.content)) {
  const msg = JSON.stringify(res.error || res).slice(0, 300);
  const error = /credit balance/i.test(msg) ? 'AI credits ran out (Anthropic account). Top up, then try again. You can still type it in.'
    : /overloaded|rate/i.test(msg) ? 'The AI is busy. Try again in a minute.' : 'The AI could not read it. Try again in a minute.';
  return [{ json: { r: { ok: false, error, detail: msg } } }];
}
if (res.stop_reason === 'refusal') return [{ json: { r: { ok: false, error: 'The AI declined this photo.' } } }];
if (res.stop_reason === 'max_tokens') return [{ json: { r: { ok: false, error: 'The AI ran out of room. Try again.' } } }];
if (res.stop_reason === 'pause_turn') return [{ json: { r: { ok: false, error: 'The brand lookup took too long. Try again, or add a note.' } } }];
// With web search the reply can hold text before/between searches; the answer is the text after the last search result.
const lastTool = res.content.map((b) => b.type).lastIndexOf('web_search_tool_result');
const text = res.content.slice(lastTool + 1).filter((b) => b.type === 'text').map((b) => b.text).join('');
let out;
try { out = JSON.parse(text); } catch { return [{ json: { r: { ok: false, error: 'The AI returned something unreadable. Try again.' } } }]; }
const items = (out.items || []).map((i) => ({ name: String(i.name || '').trim().slice(0, 60), portion: String(i.portion || '').trim().slice(0, 40),
  grams: Math.round(Number(i.grams)) || 0, kcal: Math.max(0, Math.round(Number(i.kcal)) || 0) })).filter((i) => i.name);
const u = res.usage || {};
const searches = (u.server_tool_use && u.server_tool_use.web_search_requests) || 0; // $10 per 1,000
const costUsd = Math.round((((u.input_tokens || 0) * 0.10 + (u.output_tokens || 0) * 0.50) / 1e6 + searches * 0.01) * 1e6) / 1e6;
return [{ json: { r: { ok: true, title: String(out.title || '').trim().slice(0, 80), emoji: String(out.emoji || '').slice(0, 8), items,
  kcal: items.reduce((a, i) => a + i.kcal, 0), confidence: out.confidence || 'medium', note: String(out.note || '').replace(/—/g, ',').slice(0, 300), searches, costUsd } } }];
